D=$X/dom.html F=$X/props.json node -e '
const fs=require("fs");
const fix=JSON.parse(fs.readFileSync(process.env.F,"utf8"));
const dom=fs.readFileSync(process.env.D,"utf8");
const fail=(m)=>{console.error("FAIL: "+m);process.exit(1);};
const s=fix.summary;
const exp={proposals:s.proposals,shared:s.sharedFiles,conflicts:s.conflictingPairs,changed:s.changedFiles,clean:s.cleanPairs};
const val=(k)=>{const m=dom.match(new RegExp("id=\"val-"+k+"\"[^>]*>([^<]*)"));return m?m[1].trim():null;};
for(const k of Object.keys(exp)){if(val(k)!==String(exp[k]))fail("chip "+k+" shows "+val(k)+", expected exact count "+exp[k]);}
const cls=(id)=>{const m=dom.match(new RegExp("class=\"([^\"]*)\" id=\"chip-"+id+"\""));return m?m[1]:"";};
if((cls("conflicts").indexOf("is-alert")>=0)!==(s.conflictingPairs>0))fail("conflicting-pairs chip tint wrong: "+cls("conflicts"));
